window.PROBABILITY_BOOK_DATA = {"chapter":6,"title":"Normal & exponential distributions","total":78,"range":[430,507],"questions":[{"id":430,"question":"A mobile conversation lasts X minutes, with density f(x) = (1/3)e^(−x/3) for x ≥ 0. Find P(X > 5).","page":37,"marks":1,"answer":"More than five minutes: 0.1888756","steps":[{"title":"Given and probability density","formula":"λ = 0.33333333.\nf(x) = λe^(−λx) = 0.33333333e^(−0.33333333x), x > 0."},{"title":"More than five minutes","formula":"Integrate f(x) from 5 to ∞.\n∫ (0.33333333)e^(−0.33333333x) dx  [from 5 to ∞]\n= [−e^(−0.33333333x)]  [from 5 to ∞]\n= e^(−1.6666667) ≈ 0.1888756."}],"shareImage":"share/q430.jpg","shareImageSize":[1358,266]},{"id":431,"question":"A random variable 𝑋 has an exponential\ndistribution with probability distribution function is\ngiven by\n𝑓(𝑥) = 3𝑒−3𝑥 for 𝑥 > 0\n= 0 otherwise\nFind probability that 𝑋 is not less than 2.","page":37,"marks":1,"answer":"P(X ≥ 2): 0.0024787522","steps":[{"title":"Given and probability density","formula":"λ = 3.\nf(x) = λe^(−λx) = 3e^(−3x), x > 0."},{"title":"P(X ≥ 2)","formula":"Integrate f(x) from 2 to ∞.\n∫ (3)e^(−3x) dx  [from 2 to ∞]\n= [−e^(−3x)]  [from 2 to ∞]\n= e^(−6) ≈ 0.0024787522."}],"shareImage":"share/q431.jpg","shareImageSize":[1358,331]},{"id":432,"question":"The mean and variance of the density function\nf (x) = 2e−2x are","page":37,"marks":1,"answer":"Mean = 1/2. Variance = 1/4.","steps":[{"title":"Given and formula","formula":"The density 2e^(−2x) has rate λ = 2."},{"title":"Substitution and result","formula":"Use E[X] = 1/λ and Var(X) = 1/λ²."}],"shareImage":"share/q432.jpg","shareImageSize":[1358,203]},{"id":433,"question":"If 𝑋 is random variable which follows an\nexponential distribution with parameter 𝜆 with\n𝑃(𝑋 ≤ 1) = 𝑃(𝑋 > 1) , what is 𝑉𝑎𝑟(𝑥)?","page":37,"marks":1,"answer":"1/(ln 2)²","steps":[{"title":"Given and formula","formula":"P(X ≤ 1) = P(X > 1). The probabilities sum to 1, so P(X > 1) = 1/2."},{"title":"Substitution and result","formula":"P(X > 1) = ∫ λe^(−λx) dx  [from 1 to ∞]\n= [−e^(−λx)]  [from 1 to ∞]\n= e^(−λ) = 1/2.\n∴ λ = ln 2 and Var(X) = 1/λ² = 1/(ln 2)²."}],"shareImage":"share/q433.jpg","shareImageSize":[1358,235]},{"id":434,"question":"The annual precipitation data of a city is normally\ndistributed with mean and standard deviation as\n1000 mm and 200 mm, respectively. The\nprobability that the annual precipitation will be\nmore than 1200 mm is,","page":37,"marks":1,"answer":"More than 1200 mm: 0.15865525","steps":[{"title":"Given and standardization","formula":"μ = 1000, σ = 200.\nZ = (X − μ)/σ = (X − 1000)/200."},{"title":"More than 1200 mm","formula":"When X = 1200, z = (1200 − 1000)/200 ≈ 1.\nP(Z ≥ 1) = 0.5 − P(0 ≤ Z ≤ 1)  (by symmetry about 0)\nNormal table (z to 2 decimal places): P(0 ≤ Z ≤ 1) ≈ 0.3413.\nUsing the table: 0.5 − 0.3413 = 0.1587.\n∴ P(Z ≥ 1) ≈ 0.15865525 (using unrounded values)."}],"note":"The practice book option is “less than 50%”. The calculated chance is about 15.87%.","shareImage":"share/q434.jpg","shareImageSize":[1358,297]},{"id":435,"question":"The normal probability density function curve is\nsymmetrical about the mean, µ, i.e., the area to the\nright ofthe mean is the same as the area to the left\nof the mean. This means that\n𝑃(𝑋 < µ) = 𝑃(𝑋 > µ) is equal to:","page":37,"marks":1,"answer":"0.5","steps":[{"title":"Given and formula","formula":"The two sides of a normal curve about μ have equal area."},{"title":"Substitution and result","formula":"The total area is 1 and the point X = μ has probability zero, so each side has area 0.5."}],"shareImage":"share/q435.jpg","shareImageSize":[1358,304]},{"id":436,"question":"The range of normal distribution is:","page":37,"marks":1,"answer":"(−∞, ∞)","steps":[{"title":"Given and formula","formula":"A normal density is positive at every real x."},{"title":"Substitution and result","formula":"Its support extends over all real numbers."}],"shareImage":"share/q436.jpg","shareImageSize":[1358,201]},{"id":437,"question":"If 𝑋~𝑁(100,64), then standard deviation 𝜎 is\n_____.","page":37,"marks":1,"answer":"8","steps":[{"title":"Given and formula","formula":"In N(100,64), the second parameter is σ²."},{"title":"Substitution and result","formula":"σ = √64 = 8."}],"shareImage":"share/q437.jpg","shareImageSize":[1358,202]},{"id":438,"question":"If 𝑋~𝑁 (200,49), then standard deviation 𝜎 is\n_____.","page":37,"marks":1,"answer":"7","steps":[{"title":"Given and formula","formula":"In N(200,49), the second parameter is σ²."},{"title":"Substitution and result","formula":"σ = √49 = 7."}],"shareImage":"share/q438.jpg","shareImageSize":[1358,209]},{"id":439,"question":"In a standard normal distribution, the area to the left\nof Z = 1 is:","page":37,"marks":1,"answer":"Left of Z = 1: 0.84134475","steps":[{"title":"Given and standardization","formula":"μ = 0, σ = 1.\nZ = (X − μ)/σ = (X − 0)/1."},{"title":"Left of Z = 1","formula":"When X = 1, z = (1 − 0)/1 ≈ 1.\nP(Z ≤ 1) = 0.5 + P(0 ≤ Z ≤ 1)  (by symmetry about 0)\nNormal table (z to 2 decimal places): P(0 ≤ Z ≤ 1) ≈ 0.3413.\nUsing the table: 0.5 + 0.3413 = 0.8413.\n∴ P(Z ≤ 1) ≈ 0.84134475 (using unrounded values)."}],"shareImage":"share/q439.jpg","shareImageSize":[1358,201]},{"id":440,"question":"If 𝑍 is a standard normal variate, then 𝑃(−2.33 ≤\n𝑍 ≤ 2.33) is equal to _____.","page":37,"marks":1,"answer":"Central area: 0.98019385","steps":[{"title":"Given and standardization","formula":"μ = 0, σ = 1.\nZ = (X − μ)/σ = (X − 0)/1."},{"title":"Central area","formula":"When X = -2.33, z = (-2.33 − 0)/1 ≈ -2.33.\nWhen X = 2.33, z = (2.33 − 0)/1 ≈ 2.33.\nP(-2.33 ≤ Z ≤ 2.33) = P(0 ≤ Z ≤ 2.33) + P(0 ≤ Z ≤ 2.33)  (by symmetry about 0)\nNormal table (z to 2 decimal places): P(0 ≤ Z ≤ 2.33) ≈ 0.4901.\nUsing the table: 0.4901 + 0.4901 = 0.9802.\n∴ P(-2.33 ≤ Z ≤ 2.33) ≈ 0.98019385 (using unrounded values)."}],"shareImage":"share/q440.jpg","shareImageSize":[1358,203]},{"id":441,"question":"If 𝑍 is a standard normal variate, then 𝑃(−1.65 ≤\n𝑍 ≤ 1.65) is equal to _____.","page":37,"marks":1,"answer":"Central area: 0.90105706","steps":[{"title":"Given and standardization","formula":"μ = 0, σ = 1.\nZ = (X − μ)/σ = (X − 0)/1."},{"title":"Central area","formula":"When X = -1.65, z = (-1.65 − 0)/1 ≈ -1.65.\nWhen X = 1.65, z = (1.65 − 0)/1 ≈ 1.65.\nP(-1.65 ≤ Z ≤ 1.65) = P(0 ≤ Z ≤ 1.65) + P(0 ≤ Z ≤ 1.65)  (by symmetry about 0)\nNormal table (z to 2 decimal places): P(0 ≤ Z ≤ 1.65) ≈ 0.4505.\nUsing the table: 0.4505 + 0.4505 = 0.9010.\n∴ P(-1.65 ≤ Z ≤ 1.65) ≈ 0.90105706 (using unrounded values)."}],"shareImage":"share/q441.jpg","shareImageSize":[1358,204]},{"id":442,"question":"If 𝑍 is a standard normal variate, then 𝑃(−2.58 ≤\n𝑍 ≤ 2.58) is equal to _____.","page":37,"marks":1,"answer":"Central area: 0.99011997","steps":[{"title":"Given and standardization","formula":"μ = 0, σ = 1.\nZ = (X − μ)/σ = (X − 0)/1."},{"title":"Central area","formula":"When X = -2.58, z = (-2.58 − 0)/1 ≈ -2.58.\nWhen X = 2.58, z = (2.58 − 0)/1 ≈ 2.58.\nP(-2.58 ≤ Z ≤ 2.58) = P(0 ≤ Z ≤ 2.58) + P(0 ≤ Z ≤ 2.58)  (by symmetry about 0)\nNormal table (z to 2 decimal places): P(0 ≤ Z ≤ 2.58) ≈ 0.4951.\nUsing the table: 0.4951 + 0.4951 = 0.9902.\n∴ P(-2.58 ≤ Z ≤ 2.58) ≈ 0.99011997 (using unrounded values)."}],"shareImage":"share/q442.jpg","shareImageSize":[1358,219]},{"id":443,"question":"If 𝑍 is a standard normal variate, then 𝑃(|𝑍| <\n1.96) is equal to _____.","page":37,"marks":1,"answer":"Central area: 0.95000421","steps":[{"title":"Given and standardization","formula":"μ = 0, σ = 1.\nZ = (X − μ)/σ = (X − 0)/1."},{"title":"Central area","formula":"When X = -1.96, z = (-1.96 − 0)/1 ≈ -1.96.\nWhen X = 1.96, z = (1.96 − 0)/1 ≈ 1.96.\nP(-1.96 ≤ Z ≤ 1.96) = P(0 ≤ Z ≤ 1.96) + P(0 ≤ Z ≤ 1.96)  (by symmetry about 0)\nNormal table (z to 2 decimal places): P(0 ≤ Z ≤ 1.96) ≈ 0.4750.\nUsing the table: 0.4750 + 0.4750 = 0.9500.\n∴ P(-1.96 ≤ Z ≤ 1.96) ≈ 0.95000421 (using unrounded values)."}],"shareImage":"share/q443.jpg","shareImageSize":[1358,202]},{"id":444,"question":"For a normal distribution with 𝜇 = 10,𝜎 = 2, then\nprobability of a value greater than 10 is _____.","page":37,"marks":1,"answer":"Greater than 10: 0.5","steps":[{"title":"Given and standardization","formula":"μ = 10, σ = 2.\nZ = (X − μ)/σ = (X − 10)/2."},{"title":"Greater than 10","formula":"When X = 10, z = (10 − 10)/2 ≈ 0.\nP(Z ≥ 0) = 0.5 − P(0 ≤ Z ≤ 0)  (by symmetry about 0)\nNormal table (z to 2 decimal places): P(0 ≤ Z ≤ 0) ≈ 0.0000.\nUsing the table: 0.5 − 0.0000 = 0.5000.\n∴ P(Z ≥ 0) ≈ 0.5 (using unrounded values)."}],"shareImage":"share/q444.jpg","shareImageSize":[1358,215]},{"id":445,"question":"If x is normally distributed with mean 1 and\nvariance 4, then obtain k if P ( x  k ) = 0 . 9 0","page":37,"marks":1,"answer":"k: 3.5631031","steps":[{"title":"Given and standardization","formula":"μ = 1, σ = 2.\nZ = (X − μ)/σ."},{"title":"k","formula":"P(Z ≤ z) = 0.9.\nP(0 ≤ Z ≤ |z|) = |0.9 − 0.5| = 0.4.\nUse the positive z-score: z ≈ 1.2815516.\n∴ x = μ + σz = 1 + 2(1.2815516) ≈ 3.5631031."}],"shareImage":"share/q445.jpg","shareImageSize":[1358,218]},{"id":446,"question":"The time to pass through a security screening at an\nairport follows an exponential distribution. The mean\ntime to pass through the security screening is 15\nminutes. To catch the flight, a passenger must clear th\nsecurity screening within 15 minutes. The probability\nthat the passenger will miss the flight is ______.","page":37,"marks":1,"answer":"Miss the flight: 0.36787944","steps":[{"title":"Given and probability density","formula":"λ = 0.066666667.\nf(x) = λe^(−λx) = 0.066666667e^(−0.066666667x), x > 0."},{"title":"Miss the flight","formula":"Integrate f(x) from 15 to ∞.\n∫ (0.066666667)e^(−0.066666667x) dx  [from 15 to ∞]\n= [−e^(−0.066666667x)]  [from 15 to ∞]\n= e^(−1) ≈ 0.36787944."}],"shareImage":"share/q446.jpg","shareImageSize":[1358,341]},{"id":447,"question":"A variable 𝑋 is exponentially distributed for 𝑥 ≥ 0\nwith a mean of 1. The probability that the value of 𝑋\nwill lie between 1 and 2 is _____.","page":37,"marks":1,"answer":"Between 1 and 2: 0.23254416","steps":[{"title":"Given and probability density","formula":"λ = 1.\nf(x) = λe^(−λx) = 1e^(−1x), x > 0."},{"title":"Between 1 and 2","formula":"Integrate f(x) from 1 to 2.\n∫ (1)e^(−1x) dx  [from 1 to 2]\n= [−e^(−1x)]  [from 1 to 2]\n= e^(−1) − e^(−2) ≈ 0.23254416."}],"shareImage":"share/q447.jpg","shareImageSize":[1358,235]},{"id":448,"question":"A random variable 𝑃 follows exponential distribution\nwith mean value 0.5. The expectation of 𝑃2 will be","page":37,"marks":1,"answer":"0.5","steps":[{"title":"Given and formula","formula":"An exponential variable with mean 0.5 also has SD 0.5."},{"title":"Substitution and result","formula":"E[P²] = Var(P) + E[P]² = 0.5² + 0.5² = 0.5."}],"shareImage":"share/q448.jpg","shareImageSize":[1358,215]},{"id":449,"question":"Normal Distribution is symmetric about…..","page":37,"marks":1,"answer":"The mean μ","steps":[{"title":"Given and formula","formula":"The density depends on the squared distance (x−μ)²."},{"title":"Substitution and result","formula":"Points the same distance on either side of μ have the same density."}],"shareImage":"share/q449.jpg","shareImageSize":[1358,219]},{"id":450,"question":"A personal computer has the length of time\nbetween charges of the battery is normally\ndistributed with a mean of 66 hours and a standard\ndeviation of 20 hours. What is the probability when\nthe length of time will be between 58 and 75 hours?","page":38,"marks":1,"answer":"Between 58 and 75 hours: 0.32906652","steps":[{"title":"Given and standardization","formula":"μ = 66, σ = 20.\nZ = (X − μ)/σ = (X − 66)/20."},{"title":"Between 58 and 75 hours","formula":"When X = 58, z = (58 − 66)/20 ≈ -0.4.\nWhen X = 75, z = (75 − 66)/20 ≈ 0.45.\nP(-0.4 ≤ Z ≤ 0.45) = P(0 ≤ Z ≤ 0.4) + P(0 ≤ Z ≤ 0.45)  (by symmetry about 0)\nNormal table (z to 2 decimal places): P(0 ≤ Z ≤ 0.4) ≈ 0.1554, P(0 ≤ Z ≤ 0.45) ≈ 0.1736.\nUsing the table: 0.1554 + 0.1736 = 0.3290.\n∴ P(-0.4 ≤ Z ≤ 0.45) ≈ 0.32906652 (using unrounded values)."}],"shareImage":"share/q450.jpg","shareImageSize":[1358,297]},{"id":451,"question":"Approximately what area is covered under the\nnormal distribution curve between ±3 standard\ndeviation?","page":38,"marks":1,"answer":"Within three standard deviations: 0.9973002","steps":[{"title":"Given and standardization","formula":"μ = 0, σ = 1.\nZ = (X − μ)/σ = (X − 0)/1."},{"title":"Within three standard deviations","formula":"When X = -3, z = (-3 − 0)/1 ≈ -3.\nWhen X = 3, z = (3 − 0)/1 ≈ 3.\nP(-3 ≤ Z ≤ 3) = P(0 ≤ Z ≤ 3) + P(0 ≤ Z ≤ 3)  (by symmetry about 0)\nNormal table (z to 2 decimal places): P(0 ≤ Z ≤ 3) ≈ 0.4987.\nUsing the table: 0.4987 + 0.4987 = 0.9974.\n∴ P(-3 ≤ Z ≤ 3) ≈ 0.9973002 (using unrounded values)."}],"shareImage":"share/q451.jpg","shareImageSize":[1358,233]},{"id":452,"question":"An approximate area covered within two standard-\ndeviation of the mean by standard normal variate is","page":38,"marks":1,"answer":"Within two standard deviations: 0.95449974","steps":[{"title":"Given and standardization","formula":"μ = 0, σ = 1.\nZ = (X − μ)/σ = (X − 0)/1."},{"title":"Within two standard deviations","formula":"When X = -2, z = (-2 − 0)/1 ≈ -2.\nWhen X = 2, z = (2 − 0)/1 ≈ 2.\nP(-2 ≤ Z ≤ 2) = P(0 ≤ Z ≤ 2) + P(0 ≤ Z ≤ 2)  (by symmetry about 0)\nNormal table (z to 2 decimal places): P(0 ≤ Z ≤ 2) ≈ 0.4772.\nUsing the table: 0.4772 + 0.4772 = 0.9544.\n∴ P(-2 ≤ Z ≤ 2) ≈ 0.95449974 (using unrounded values)."}],"shareImage":"share/q452.jpg","shareImageSize":[1358,202]},{"id":453,"question":"Let X be a normal random variable with mean zero\nand variance 9. If 𝑎 = 𝑃(𝑋 ≥ 3), 𝑡ℎ𝑒𝑛 𝑃(|𝑋| ≤ 3)\nequal to….","page":38,"marks":1,"answer":"1 − 2a","steps":[{"title":"Given and formula","formula":"Symmetry gives P(X ≤ −3) = P(X ≥ 3) = a."},{"title":"Substitution and result","formula":"Subtract both tails from 1. Equality at individual points does not affect the probability."}],"shareImage":"share/q453.jpg","shareImageSize":[1358,234]},{"id":454,"question":"Let 𝑋 be normal variate with mean 0 and SD 5. If\n𝑃(𝑋 < 5) = 𝑘 then 𝑃(|𝑋| ≥ 5) will be","page":38,"marks":1,"answer":"2(1 − k)","steps":[{"title":"Given and formula","formula":"P(X ≥ 5) = 1 − k. Symmetry gives the same probability below −5."},{"title":"Substitution and result","formula":"Add the disjoint tails to obtain 2(1 − k)."}],"shareImage":"share/q454.jpg","shareImageSize":[1358,202]},{"id":455,"question":"The mean of a normal distribution is the average of\nthe first ten natural numbers then what is the\nprobability of variable between 4 and 7 if\n𝑃(𝑋 ≤ 4) = 1/5","page":38,"marks":1,"answer":"3/5","steps":[{"title":"Given and formula","formula":"The mean is (1+10)/2 = 5.5. The endpoints 4 and 7 are equally far from 5.5."},{"title":"Substitution and result","formula":"Each outside tail has probability 1/5. The middle has probability 1 − 2/5 = 3/5."}],"shareImage":"share/q455.jpg","shareImageSize":[1358,266]},{"id":456,"question":"For a standard normal variate, the value of mean is?","page":38,"marks":1,"answer":"0","steps":[{"title":"Given and formula","formula":"The standard normal distribution is N(0,1)."},{"title":"Substitution and result","formula":"Its first parameter, the mean, is 0."}],"shareImage":"share/q456.jpg","shareImageSize":[1358,190]},{"id":457,"question":"The standard normal curve is symmetric about the\nvalue….","page":38,"marks":1,"answer":"0","steps":[{"title":"Given and formula","formula":"The standard normal has μ = 0."},{"title":"Substitution and result","formula":"The density has the same height at z and −z, so its axis of symmetry is z = 0."}],"shareImage":"share/q457.jpg","shareImageSize":[1358,201]},{"id":458,"question":"For a standard normal probability distribution, the\nmean (µ) and the standard deviation (s)","page":38,"marks":1,"answer":"μ = 0, σ = 1","steps":[{"title":"Given and formula","formula":"Standardize by using Z = (X−μ)/σ."},{"title":"Substitution and result","formula":"Then E[Z] = 0 and Var(Z) = 1, giving SD = 1."}],"shareImage":"share/q458.jpg","shareImageSize":[1358,202]},{"id":459,"question":"If Y = 5X + 10 and X is N (10,25), then mean of Y\nis?","page":38,"marks":1,"answer":"60","steps":[{"title":"Given and formula","formula":"Linearity of expectation gives E[Y] = 5E[X] + 10."},{"title":"Substitution and result","formula":"E[Y] = 5(10) + 10 = 60."}],"shareImage":"share/q459.jpg","shareImageSize":[1358,221]},{"id":460,"question":"In a company, amount of light bills follows normal\ndistribution with 𝜎 = 60.\n11.31% of customers pay bill less than 260.The\naverage amount of light bill is _____.","page":38,"marks":1,"answer":"332.61234","steps":[{"title":"Given and formula","formula":"P(X < 260) = 0.1131 gives z = Φ⁻¹(0.1131) ≈ −1.21."},{"title":"Substitution and result","formula":"(260 − μ)/60 ≈ −1.21, so μ ≈ 332.6."}],"shareImage":"share/q460.jpg","shareImageSize":[1358,266]},{"id":461,"question":"If the distribution of a normal variable is shown as\n𝑁(20,4) then which of the following intervals\nincludes 99.73% observations?","page":38,"marks":1,"answer":"(14, 26)","steps":[{"title":"Given and formula","formula":"A central normal interval of roughly 99.73% is μ ± 3σ."},{"title":"Substitution and result","formula":"Here μ = 20 and σ = √4 = 2, so the endpoints are 20 ± 6."}],"shareImage":"share/q461.jpg","shareImageSize":[1358,234]},{"id":462,"question":"For Normal distribution with mean 2 and variance\n9. Find the value of x such that the probability of\nthe interval [2,𝑥] is 0.4115","page":38,"marks":1,"answer":"x: 6.0501495","steps":[{"title":"Given and standardization","formula":"μ = 2, σ = 3.\nZ = (X − μ)/σ."},{"title":"x","formula":"P(Z ≤ z) = 0.9115.\nP(0 ≤ Z ≤ |z|) = |0.9115 − 0.5| = 0.4115.\nUse the positive z-score: z ≈ 1.3500498.\n∴ x = μ + σz = 2 + 3(1.3500498) ≈ 6.0501495."}],"shareImage":"share/q462.jpg","shareImageSize":[1358,234]},{"id":463,"question":"If 𝑋 is a normal variate with a mean of 30 and an\nSD of 5, find (i) 𝑃(26 ≤ 𝑋 ≤ 40)\n(ii) 𝑃(𝑋 ≥ 45).","page":38,"marks":2,"answer":"Between 26 and 40: 0.76539447 · At least 45: 0.001349898","steps":[{"title":"Given and standardization","formula":"μ = 30, σ = 5.\nZ = (X − μ)/σ = (X − 30)/5."},{"title":"Between 26 and 40","formula":"When X = 26, z = (26 − 30)/5 ≈ -0.8.\nWhen X = 40, z = (40 − 30)/5 ≈ 2.\nP(-0.8 ≤ Z ≤ 2) = P(0 ≤ Z ≤ 0.8) + P(0 ≤ Z ≤ 2)  (by symmetry about 0)\nNormal table (z to 2 decimal places): P(0 ≤ Z ≤ 0.8) ≈ 0.2881, P(0 ≤ Z ≤ 2) ≈ 0.4772.\nUsing the table: 0.2881 + 0.4772 = 0.7653.\n∴ P(-0.8 ≤ Z ≤ 2) ≈ 0.76539447 (using unrounded values)."},{"title":"At least 45","formula":"When X = 45, z = (45 − 30)/5 ≈ 3.\nP(Z ≥ 3) = 0.5 − P(0 ≤ Z ≤ 3)  (by symmetry about 0)\nNormal table (z to 2 decimal places): P(0 ≤ Z ≤ 3) ≈ 0.4987.\nUsing the table: 0.5 − 0.4987 = 0.0013.\n∴ P(Z ≥ 3) ≈ 0.001349898 (using unrounded values)."}],"shareImage":"share/q463.jpg","shareImageSize":[760,235]},{"id":464,"question":"If 𝑋 is normally distributed with a mean of 2 and an\nSD of 0.1, find 𝑃(|𝑋 − 2| ≥ 0.01)?","page":38,"marks":2,"answer":"0.92034433","steps":[{"title":"Given and formula","formula":"μ = 2, σ = 0.1.\nZ = (X − 2)/0.1.\n|X − 2| < 0.01 means 1.99 < X < 2.01.\nAt X = 1.99, z = −0.1. At X = 2.01, z = 0.1."},{"title":"Substitution and result","formula":"P(|X − 2| ≥ 0.01) = 1 − P(−0.1 < Z < 0.1)\n= 1 − 2P(0 ≤ Z ≤ 0.1)  (by symmetry)\n≈ 1 − 2(0.039827837) ≈ 0.92034433."}],"shareImage":"share/q464.jpg","shareImageSize":[760,203]},{"id":465,"question":"Assume that the mean height of Indian soldiers is\n68.22 inches with a variance of 10.8 inches. How\nmany soldiers in a regiment of 1000 would you\nexpect to be over 6 feet tall?","page":38,"marks":3,"answer":"Over 72 inches: about 125 out of 1000","steps":[{"title":"Given and standardization","formula":"μ = 68.22, σ = 3.2863353.\nZ = (X − μ)/σ = (X − 68.22)/3.2863353."},{"title":"Over 72 inches","formula":"When X = 72, z = (72 − 68.22)/3.2863353 ≈ 1.1502174.\nP(Z ≥ 1.1502174) = 0.5 − P(0 ≤ Z ≤ 1.1502174)  (by symmetry about 0)\nNormal table (z to 2 decimal places): P(0 ≤ Z ≤ 1.15) ≈ 0.3749.\nUsing the table: 0.5 − 0.3749 = 0.1251.\n∴ P(Z ≥ 1.1502174) ≈ 0.12502718 (using unrounded values).\nExpected number = 1000 × 0.12502718 ≈ 125.02718."}],"note":"Convert six feet to 72 inches and take the square root of the given variance.","shareImage":"share/q465.jpg","shareImageSize":[760,265]},{"id":466,"question":"The marks obtained by students in a college are\nnormally distributed with a mean of 65 and a\nvariance of 25. If 3 students are selected at random\nfrom this college, what is the probability that at\nleast one of them would have scored more than 75\nmarks?","page":38,"marks":3,"answer":"0.066709465","steps":[{"title":"Given and formula","formula":"A student scores at most 75 with probability Φ((75−65)/5) = Φ(2)."},{"title":"Substitution and result","formula":"Assuming independent selections, P(at least one above 75) = 1 − [Φ(2)]³."}],"shareImage":"share/q466.jpg","shareImageSize":[760,328]},{"id":467,"question":"If 𝑋 is normally distributed with a mean and\nstandard deviation of 4, find\n(i) 𝑃(5 ≤ 𝑋 ≤ 10) (ii) 𝑃(𝑋 ≥ 15)\n(iii) 𝑃(10 ≤ 𝑋 ≤ 15) (iv) 𝑃(𝑋 ≤ 5).","page":38,"marks":4,"answer":"Between 5 and 10: 0.33448647 · At least 15: 0.0029797632 · Between 10 and 15: 0.063827438 · At most 5: 0.59870633","steps":[{"title":"Given and standardization","formula":"μ = 4, σ = 4.\nZ = (X − μ)/σ = (X − 4)/4."},{"title":"Between 5 and 10","formula":"When X = 5, z = (5 − 4)/4 ≈ 0.25.\nWhen X = 10, z = (10 − 4)/4 ≈ 1.5.\nP(0.25 ≤ Z ≤ 1.5) = P(0 ≤ Z ≤ 1.5) − P(0 ≤ Z ≤ 0.25)  (by symmetry about 0)\nNormal table (z to 2 decimal places): P(0 ≤ Z ≤ 0.25) ≈ 0.0987, P(0 ≤ Z ≤ 1.5) ≈ 0.4332.\nUsing the table: 0.4332 − 0.0987 = 0.3345.\n∴ P(0.25 ≤ Z ≤ 1.5) ≈ 0.33448647 (using unrounded values)."},{"title":"At least 15","formula":"When X = 15, z = (15 − 4)/4 ≈ 2.75.\nP(Z ≥ 2.75) = 0.5 − P(0 ≤ Z ≤ 2.75)  (by symmetry about 0)\nNormal table (z to 2 decimal places): P(0 ≤ Z ≤ 2.75) ≈ 0.4970.\nUsing the table: 0.5 − 0.4970 = 0.0030.\n∴ P(Z ≥ 2.75) ≈ 0.0029797632 (using unrounded values)."},{"title":"Between 10 and 15","formula":"When X = 10, z = (10 − 4)/4 ≈ 1.5.\nWhen X = 15, z = (15 − 4)/4 ≈ 2.75.\nP(1.5 ≤ Z ≤ 2.75) = P(0 ≤ Z ≤ 2.75) − P(0 ≤ Z ≤ 1.5)  (by symmetry about 0)\nNormal table (z to 2 decimal places): P(0 ≤ Z ≤ 1.5) ≈ 0.4332, P(0 ≤ Z ≤ 2.75) ≈ 0.4970.\nUsing the table: 0.4970 − 0.4332 = 0.0638.\n∴ P(1.5 ≤ Z ≤ 2.75) ≈ 0.063827438 (using unrounded values)."},{"title":"At most 5","formula":"When X = 5, z = (5 − 4)/4 ≈ 0.25.\nP(Z ≤ 0.25) = 0.5 + P(0 ≤ Z ≤ 0.25)  (by symmetry about 0)\nNormal table (z to 2 decimal places): P(0 ≤ Z ≤ 0.25) ≈ 0.0987.\nUsing the table: 0.5 + 0.0987 = 0.5987.\n∴ P(Z ≤ 0.25) ≈ 0.59870633 (using unrounded values)."}],"shareImage":"share/q467.jpg","shareImageSize":[760,267]},{"id":468,"question":"The compressive strength of samples of cement can\nbe modelled by a normal distribution with a mean\n6000 kilograms per square centimeter a standard\ndeviation of 100 kilograms per square centimeter.\n(i)What is the probability that a sample's strength is\nless than 6250 Kg/cm²?\n(ii) What is the probability if sample strength is\nbetween 5800 and 5900 Kg/cm²?\n(iii) What strength is exceeded by 95% of the\nsamples?","page":38,"marks":4,"answer":"(i) 0.99379033. (ii) 0.13590512. (iii) 5835.5146 kg/cm².","steps":[{"title":"Standardize the strength","formula":"Use z = (x−6000)/100."},{"title":"Calculate the two probabilities","formula":"(i) Φ(2.5). (ii) Φ(−1) − Φ(−2)."},{"title":"Find the strength exceeded by 95%","formula":"The left tail is 5%, so z = Φ⁻¹(0.05) ≈ −1.64485. Convert back using x = 6000 + 100z."}],"shareImage":"share/q468.jpg","shareImageSize":[760,511]},{"id":469,"question":"In a photographic process, the developing time of\nprints may be looked upon as a random variable\nhaving the normal distribution with a mean of 16.28\nseconds and a standard deviation of 0.12 second.\nFind the probability that it will take\n(i) anywhere from 16.00 to 16.50 seconds to develop\none of the prints;\n(ii) at least 16.20 seconds to develop one of the\nprints;\n(iii) at most 16.35 seconds to develop one of the\nprints.","page":39,"marks":4,"answer":"Between 16.00 and 16.50 seconds: 0.95680816 · At least 16.20 seconds: 0.74750746 · At most 16.35 seconds: 0.72016554","steps":[{"title":"Given and standardization","formula":"μ = 16.28, σ = 0.12.\nZ = (X − μ)/σ = (X − 16.28)/0.12."},{"title":"Between 16.00 and 16.50 seconds","formula":"When X = 16, z = (16 − 16.28)/0.12 ≈ -2.3333333.\nWhen X = 16.5, z = (16.5 − 16.28)/0.12 ≈ 1.8333333.\nP(-2.3333333 ≤ Z ≤ 1.8333333) = P(0 ≤ Z ≤ 2.3333333) + P(0 ≤ Z ≤ 1.8333333)  (by symmetry about 0)\nNormal table (z to 2 decimal places): P(0 ≤ Z ≤ 2.33) ≈ 0.4901, P(0 ≤ Z ≤ 1.83) ≈ 0.4664.\nUsing the table: 0.4901 + 0.4664 = 0.9565.\n∴ P(-2.3333333 ≤ Z ≤ 1.8333333) ≈ 0.95680816 (using unrounded values)."},{"title":"At least 16.20 seconds","formula":"When X = 16.2, z = (16.2 − 16.28)/0.12 ≈ -0.66666667.\nP(Z ≥ -0.66666667) = 0.5 + P(0 ≤ Z ≤ 0.66666667)  (by symmetry about 0)\nNormal table (z to 2 decimal places): P(0 ≤ Z ≤ 0.67) ≈ 0.2486.\nUsing the table: 0.5 + 0.2486 = 0.7486.\n∴ P(Z ≥ -0.66666667) ≈ 0.74750746 (using unrounded values)."},{"title":"At most 16.35 seconds","formula":"When X = 16.35, z = (16.35 − 16.28)/0.12 ≈ 0.58333333.\nP(Z ≤ 0.58333333) = 0.5 + P(0 ≤ Z ≤ 0.58333333)  (by symmetry about 0)\nNormal table (z to 2 decimal places): P(0 ≤ Z ≤ 0.58) ≈ 0.2190.\nUsing the table: 0.5 + 0.2190 = 0.7190.\n∴ P(Z ≤ 0.58333333) ≈ 0.72016554 (using unrounded values)."}],"shareImage":"share/q469.jpg","shareImageSize":[760,488]},{"id":470,"question":"Weights of 500 students of a college are normally\ndistributed with average weight 95 lbs and standard\ndeviation 7.5. find how many students have the\nweight between 100 and 110 lbs.","page":39,"marks":3,"answer":"Between 100 and 110 lb: about 115 out of 500","steps":[{"title":"Given and standardization","formula":"μ = 95, σ = 7.5.\nZ = (X − μ)/σ = (X − 95)/7.5."},{"title":"Between 100 and 110 lb","formula":"When X = 100, z = (100 − 95)/7.5 ≈ 0.66666667.\nWhen X = 110, z = (110 − 95)/7.5 ≈ 2.\nP(0.66666667 ≤ Z ≤ 2) = P(0 ≤ Z ≤ 2) − P(0 ≤ Z ≤ 0.66666667)  (by symmetry about 0)\nNormal table (z to 2 decimal places): P(0 ≤ Z ≤ 0.67) ≈ 0.2486, P(0 ≤ Z ≤ 2) ≈ 0.4772.\nUsing the table: 0.4772 − 0.2486 = 0.2286.\n∴ P(0.66666667 ≤ Z ≤ 2) ≈ 0.22974241 (using unrounded values).\nExpected number = 500 × 0.22974241 ≈ 114.8712."}],"shareImage":"share/q470.jpg","shareImageSize":[760,265]},{"id":471,"question":"Let X have density f(x) = (1/5)e^(−x/5) for x > 0, and 0 otherwise. Find (i) P(X > 5), (ii) P(3 ≤ X ≤ 6), (iii) its mean and (iv) its variance.","page":39,"marks":3,"answer":"P(X > 5): 0.36787944 · P(3 ≤ X ≤ 6): 0.24761742 · Mean = 5, variance = 25","steps":[{"title":"Given and probability density","formula":"λ = 0.2.\nf(x) = λe^(−λx) = 0.2e^(−0.2x), x > 0."},{"title":"P(X > 5)","formula":"Integrate f(x) from 5 to ∞.\n∫ (0.2)e^(−0.2x) dx  [from 5 to ∞]\n= [−e^(−0.2x)]  [from 5 to ∞]\n= e^(−1) ≈ 0.36787944."},{"title":"P(3 ≤ X ≤ 6)","formula":"Integrate f(x) from 3 to 6.\n∫ (0.2)e^(−0.2x) dx  [from 3 to 6]\n= [−e^(−0.2x)]  [from 3 to 6]\n= e^(−0.6) − e^(−1.2) ≈ 0.24761742."},{"title":"Find mean and variance","formula":"E[X] = 1/λ = 1/(1/5) = 5.\nVar(X) = 1/λ² = 1/(1/5)² = 25."}],"shareImage":"share/q471.jpg","shareImageSize":[760,330]},{"id":472,"question":"If the weights of 300 students are normally\ndistributed with a mean of 68 kg and a standard\ndeviation of 3 kg, how many students have weights\n(i) greater than 72 kg? (ii) less than or equal to 64\nkg? (iii) between 65 kg and 71 kg inclusive?","page":39,"marks":4,"answer":"Above 72 kg: about 27 out of 300 · At most 64 kg: about 27 out of 300 · 65 to 71 kg: about 205 out of 300","steps":[{"title":"Given and standardization","formula":"μ = 68, σ = 3.\nZ = (X − μ)/σ = (X − 68)/3."},{"title":"Above 72 kg","formula":"When X = 72, z = (72 − 68)/3 ≈ 1.3333333.\nP(Z ≥ 1.3333333) = 0.5 − P(0 ≤ Z ≤ 1.3333333)  (by symmetry about 0)\nNormal table (z to 2 decimal places): P(0 ≤ Z ≤ 1.33) ≈ 0.4082.\nUsing the table: 0.5 − 0.4082 = 0.0918.\n∴ P(Z ≥ 1.3333333) ≈ 0.09121122 (using unrounded values).\nExpected number = 300 × 0.09121122 ≈ 27.363366."},{"title":"At most 64 kg","formula":"When X = 64, z = (64 − 68)/3 ≈ -1.3333333.\nP(Z ≤ -1.3333333) = 0.5 − P(0 ≤ Z ≤ 1.3333333)  (by symmetry about 0)\nNormal table (z to 2 decimal places): P(0 ≤ Z ≤ 1.33) ≈ 0.4082.\nUsing the table: 0.5 − 0.4082 = 0.0918.\n∴ P(Z ≤ -1.3333333) ≈ 0.09121122 (using unrounded values).\nExpected number = 300 × 0.09121122 ≈ 27.363366."},{"title":"65 to 71 kg","formula":"When X = 65, z = (65 − 68)/3 ≈ -1.\nWhen X = 71, z = (71 − 68)/3 ≈ 1.\nP(-1 ≤ Z ≤ 1) = P(0 ≤ Z ≤ 1) + P(0 ≤ Z ≤ 1)  (by symmetry about 0)\nNormal table (z to 2 decimal places): P(0 ≤ Z ≤ 1) ≈ 0.3413.\nUsing the table: 0.3413 + 0.3413 = 0.6826.\n∴ P(-1 ≤ Z ≤ 1) ≈ 0.68268949 (using unrounded values).\nExpected number = 300 × 0.68268949 ≈ 204.80685."}],"shareImage":"share/q472.jpg","shareImageSize":[760,300]},{"id":473,"question":"What is the probability that a standard normal\nvariate 𝑍 will be (i) greater than 1.09 ? (ii) less than\n−1.65? (iii) lying between −1 and 1.96? (iv) lying\nbetween 1.25 and 2.75?","page":39,"marks":4,"answer":"Greater than 1.09: 0.13785657 · Less than −1.65: 0.049471468 · Between −1 and 1.96: 0.81634685 · Between 1.25 and 2.75: 0.10267001","steps":[{"title":"Given and standardization","formula":"μ = 0, σ = 1.\nZ = (X − μ)/σ = (X − 0)/1."},{"title":"Greater than 1.09","formula":"When X = 1.09, z = (1.09 − 0)/1 ≈ 1.09.\nP(Z ≥ 1.09) = 0.5 − P(0 ≤ Z ≤ 1.09)  (by symmetry about 0)\nNormal table (z to 2 decimal places): P(0 ≤ Z ≤ 1.09) ≈ 0.3621.\nUsing the table: 0.5 − 0.3621 = 0.1379.\n∴ P(Z ≥ 1.09) ≈ 0.13785657 (using unrounded values)."},{"title":"Less than −1.65","formula":"When X = -1.65, z = (-1.65 − 0)/1 ≈ -1.65.\nP(Z ≤ -1.65) = 0.5 − P(0 ≤ Z ≤ 1.65)  (by symmetry about 0)\nNormal table (z to 2 decimal places): P(0 ≤ Z ≤ 1.65) ≈ 0.4505.\nUsing the table: 0.5 − 0.4505 = 0.0495.\n∴ P(Z ≤ -1.65) ≈ 0.049471468 (using unrounded values)."},{"title":"Between −1 and 1.96","formula":"When X = -1, z = (-1 − 0)/1 ≈ -1.\nWhen X = 1.96, z = (1.96 − 0)/1 ≈ 1.96.\nP(-1 ≤ Z ≤ 1.96) = P(0 ≤ Z ≤ 1) + P(0 ≤ Z ≤ 1.96)  (by symmetry about 0)\nNormal table (z to 2 decimal places): P(0 ≤ Z ≤ 1) ≈ 0.3413, P(0 ≤ Z ≤ 1.96) ≈ 0.4750.\nUsing the table: 0.3413 + 0.4750 = 0.8163.\n∴ P(-1 ≤ Z ≤ 1.96) ≈ 0.81634685 (using unrounded values)."},{"title":"Between 1.25 and 2.75","formula":"When X = 1.25, z = (1.25 − 0)/1 ≈ 1.25.\nWhen X = 2.75, z = (2.75 − 0)/1 ≈ 2.75.\nP(1.25 ≤ Z ≤ 2.75) = P(0 ≤ Z ≤ 2.75) − P(0 ≤ Z ≤ 1.25)  (by symmetry about 0)\nNormal table (z to 2 decimal places): P(0 ≤ Z ≤ 1.25) ≈ 0.3944, P(0 ≤ Z ≤ 2.75) ≈ 0.4970.\nUsing the table: 0.4970 − 0.3944 = 0.1026.\n∴ P(1.25 ≤ Z ≤ 2.75) ≈ 0.10267001 (using unrounded values)."}],"shareImage":"share/q473.jpg","shareImageSize":[760,267]},{"id":474,"question":"The continuous random variable 𝑍 has a standard\nnormal distribution. Calculate the probability of the\nfollowing. (a) 𝑍 < 1.3 (b) 𝑍 > 1.3 (c) 𝑍 > −1.3\n(d) 𝑍 < −1.3 (e) −1.37 ≤ 𝑍 ≤ 2.01 (f) |𝑍| ≤ 0.5\n(g) −1.79 ≤ 𝑍 ≤ −0.54","page":39,"marks":5,"answer":"(a): 0.90319952 · (b): 0.096800485 · (c): 0.90319952 · (d): 0.096800485 · (e): 0.89244095 · (f): 0.38292492 · (g): 0.25787156","steps":[{"title":"Given and standardization","formula":"μ = 0, σ = 1.\nZ = (X − μ)/σ = (X − 0)/1."},{"title":"(a)","formula":"When X = 1.3, z = (1.3 − 0)/1 ≈ 1.3.\nP(Z ≤ 1.3) = 0.5 + P(0 ≤ Z ≤ 1.3)  (by symmetry about 0)\nNormal table (z to 2 decimal places): P(0 ≤ Z ≤ 1.3) ≈ 0.4032.\nUsing the table: 0.5 + 0.4032 = 0.9032.\n∴ P(Z ≤ 1.3) ≈ 0.90319952 (using unrounded values)."},{"title":"(b)","formula":"When X = 1.3, z = (1.3 − 0)/1 ≈ 1.3.\nP(Z ≥ 1.3) = 0.5 − P(0 ≤ Z ≤ 1.3)  (by symmetry about 0)\nNormal table (z to 2 decimal places): P(0 ≤ Z ≤ 1.3) ≈ 0.4032.\nUsing the table: 0.5 − 0.4032 = 0.0968.\n∴ P(Z ≥ 1.3) ≈ 0.096800485 (using unrounded values)."},{"title":"(c)","formula":"When X = -1.3, z = (-1.3 − 0)/1 ≈ -1.3.\nP(Z ≥ -1.3) = 0.5 + P(0 ≤ Z ≤ 1.3)  (by symmetry about 0)\nNormal table (z to 2 decimal places): P(0 ≤ Z ≤ 1.3) ≈ 0.4032.\nUsing the table: 0.5 + 0.4032 = 0.9032.\n∴ P(Z ≥ -1.3) ≈ 0.90319952 (using unrounded values)."},{"title":"(d)","formula":"When X = -1.3, z = (-1.3 − 0)/1 ≈ -1.3.\nP(Z ≤ -1.3) = 0.5 − P(0 ≤ Z ≤ 1.3)  (by symmetry about 0)\nNormal table (z to 2 decimal places): P(0 ≤ Z ≤ 1.3) ≈ 0.4032.\nUsing the table: 0.5 − 0.4032 = 0.0968.\n∴ P(Z ≤ -1.3) ≈ 0.096800485 (using unrounded values)."},{"title":"(e)","formula":"When X = -1.37, z = (-1.37 − 0)/1 ≈ -1.37.\nWhen X = 2.01, z = (2.01 − 0)/1 ≈ 2.01.\nP(-1.37 ≤ Z ≤ 2.01) = P(0 ≤ Z ≤ 1.37) + P(0 ≤ Z ≤ 2.01)  (by symmetry about 0)\nNormal table (z to 2 decimal places): P(0 ≤ Z ≤ 1.37) ≈ 0.4147, P(0 ≤ Z ≤ 2.01) ≈ 0.4778.\nUsing the table: 0.4147 + 0.4778 = 0.8925.\n∴ P(-1.37 ≤ Z ≤ 2.01) ≈ 0.89244095 (using unrounded values)."},{"title":"(f)","formula":"When X = -0.5, z = (-0.5 − 0)/1 ≈ -0.5.\nWhen X = 0.5, z = (0.5 − 0)/1 ≈ 0.5.\nP(-0.5 ≤ Z ≤ 0.5) = P(0 ≤ Z ≤ 0.5) + P(0 ≤ Z ≤ 0.5)  (by symmetry about 0)\nNormal table (z to 2 decimal places): P(0 ≤ Z ≤ 0.5) ≈ 0.1915.\nUsing the table: 0.1915 + 0.1915 = 0.3830.\n∴ P(-0.5 ≤ Z ≤ 0.5) ≈ 0.38292492 (using unrounded values)."},{"title":"(g)","formula":"When X = -1.79, z = (-1.79 − 0)/1 ≈ -1.79.\nWhen X = -0.54, z = (-0.54 − 0)/1 ≈ -0.54.\nP(-1.79 ≤ Z ≤ -0.54) = P(0 ≤ Z ≤ 1.79) − P(0 ≤ Z ≤ 0.54)  (by symmetry about 0)\nNormal table (z to 2 decimal places): P(0 ≤ Z ≤ 1.79) ≈ 0.4633, P(0 ≤ Z ≤ 0.54) ≈ 0.2054.\nUsing the table: 0.4633 − 0.2054 = 0.2579.\n∴ P(-1.79 ≤ Z ≤ -0.54) ≈ 0.25787156 (using unrounded values)."}],"shareImage":"share/q474.jpg","shareImageSize":[760,299]},{"id":475,"question":"Fit a normal distribution to the data below. Use μ = 43.7 and σ = 14.8.","page":39,"marks":4,"answer":"Expected frequencies in the printed classes: 9.5784991, 26.568755, 47.462307, 54.628759, 40.516898, 19.35945, 5.9559755.","steps":[{"title":"Given and distribution parameters","formula":"Use the given mean and standard deviation.\nN = 208, μ ≈ 43.7, σ ≈ 14.8."},{"title":"Find the class boundaries","formula":"Boundaries: 10.5, 20.5, 30.5, 40.5, 50.5, 60.5, 70.5, 80.5. Use the midpoint between adjacent values or between the ends of adjacent classes."},{"title":"Calculate the expected frequencies","formula":"For each interval (a,b), first find z₁ = (a − μ)/σ and z₂ = (b − μ)/σ.\nUse areas measured from 0 and symmetry to calculate P(z₁ ≤ Z ≤ z₂).\nExpected frequency = 208 × P(z₁ ≤ Z ≤ z₂)."}],"table":{"headers":["Class or value","Frequency"],"rows":[["11–20",20],["21–30",28],["31–40",40],["41–50",60],["51–60",32],["61–70",20],["71–80",8]]},"workingTable":{"headers":["Class or value","Observed","Lower z","Upper z","Class probability","Expected N × P"],"rows":[["Below 10.5","","−∞","-2.2432432","0.012440567","2.5876378"],["11–20",20,"-2.2432432","-1.5675676","0.046050476","9.5784991"],["21–30",28,"-1.5675676","-0.89189189","0.1277344","26.568755"],["31–40",40,"-0.89189189","-0.21621622","0.22818417","47.462307"],["41–50",60,"-0.21621622","0.45945946","0.26263826","54.628759"],["51–60",32,"0.45945946","1.1351351","0.19479278","40.516898"],["61–70",20,"1.1351351","1.8108108","0.09307428","19.35945"],["71–80",8,"1.8108108","2.4864865","0.028634498","5.9559755"],["Above 80.5","","2.4864865","∞","0.0064505735","1.3417193"]]},"shareImage":"share/q475.jpg","shareImageSize":[760,547]},{"id":476,"question":"The income distribution of officers of a certain\ncompany was found to follow normal distribution.\nThe average income of an officer was Rs. 15,000.\nThe standard deviation of the income of officers\nwas Rs. 5,000. If there were 242 officers drawing\nsalary above Rs. 18,500, how many officers were\nthere in the company?","page":39,"marks":3,"answer":"About 1000 officers.","steps":[{"title":"Given and formula","formula":"P(salary > 18500) = 1 − Φ((18500−15000)/5000) = 1 − Φ(0.7)."},{"title":"Substitution and result","formula":"If there are N officers, N × [1 − Φ(0.7)] = 242. Divide 242 by this tail probability."}],"shareImage":"share/q476.jpg","shareImageSize":[760,389]},{"id":477,"question":"The life -time in hours of a certain electrical\nequipment has the normal distribution with mean =\n80 and standard deviation = 16. (i) What is the\nprobability that the equipment lasts at least\n100hours? (ii) If the equipment has already lasted\n88 hours, what is the conditional probability that it\nwill last at least another 12 hours?","page":40,"marks":3,"answer":"(i) 0.10564977. (ii) 0.34242113.","steps":[{"title":"Find the chance of lasting 100 hours","formula":"P(X ≥ 100) = 1 − Φ((100−80)/16) = 1 − Φ(1.25)."},{"title":"Condition on lasting 88 hours","formula":"Divide P(X ≥ 100) by P(X > 88) = 1 − Φ(0.5), since reaching 100 hours implies reaching 88 hours."}],"shareImage":"share/q477.jpg","shareImageSize":[760,363]},{"id":478,"question":"Find the area under the normal curve in each of the\ncases\n(I) In between z = – 0.68 and z = 0;\n(II) In between z = 0.81 and z = 1.94; and\n(III) Right of z = –1. 28.","page":40,"marks":3,"answer":"(i): 0.25174777 · (ii): 0.18278024 · (iii): 0.89972743","steps":[{"title":"Given and standardization","formula":"μ = 0, σ = 1.\nZ = (X − μ)/σ = (X − 0)/1."},{"title":"(i)","formula":"When X = -0.68, z = (-0.68 − 0)/1 ≈ -0.68.\nWhen X = 0, z = (0 − 0)/1 ≈ 0.\nP(-0.68 ≤ Z ≤ 0) = P(0 ≤ Z ≤ 0.68) − P(0 ≤ Z ≤ 0)  (by symmetry about 0)\nNormal table (z to 2 decimal places): P(0 ≤ Z ≤ 0.68) ≈ 0.2517, P(0 ≤ Z ≤ 0) ≈ 0.0000.\nUsing the table: 0.2517 − 0.0000 = 0.2517.\n∴ P(-0.68 ≤ Z ≤ 0) ≈ 0.25174777 (using unrounded values)."},{"title":"(ii)","formula":"When X = 0.81, z = (0.81 − 0)/1 ≈ 0.81.\nWhen X = 1.94, z = (1.94 − 0)/1 ≈ 1.94.\nP(0.81 ≤ Z ≤ 1.94) = P(0 ≤ Z ≤ 1.94) − P(0 ≤ Z ≤ 0.81)  (by symmetry about 0)\nNormal table (z to 2 decimal places): P(0 ≤ Z ≤ 0.81) ≈ 0.2910, P(0 ≤ Z ≤ 1.94) ≈ 0.4738.\nUsing the table: 0.4738 − 0.2910 = 0.1828.\n∴ P(0.81 ≤ Z ≤ 1.94) ≈ 0.18278024 (using unrounded values)."},{"title":"(iii)","formula":"When X = -1.28, z = (-1.28 − 0)/1 ≈ -1.28.\nP(Z ≥ -1.28) = 0.5 + P(0 ≤ Z ≤ 1.28)  (by symmetry about 0)\nNormal table (z to 2 decimal places): P(0 ≤ Z ≤ 1.28) ≈ 0.3997.\nUsing the table: 0.5 + 0.3997 = 0.8997.\n∴ P(Z ≥ -1.28) ≈ 0.89972743 (using unrounded values)."}],"shareImage":"share/q478.jpg","shareImageSize":[760,297]},{"id":479,"question":"Fit a normal distribution to the data below. Use μ = 165.5 and σ = 15.26.","page":40,"marks":3,"answer":"Expected frequencies in the printed classes: 0.85666284, 3.7357224, 10.752227, 20.438715, 25.669375, 21.303331, 11.681478, 4.230597, 1.0113365.","steps":[{"title":"Given and distribution parameters","formula":"Use the given mean and standard deviation.\nN = 100, μ ≈ 165.5, σ ≈ 15.26."},{"title":"Find the class boundaries","formula":"Boundaries: 120, 130, 140, 150, 160, 170, 180, 190, 200, 210. Use the midpoint between adjacent values or between the ends of adjacent classes."},{"title":"Calculate the expected frequencies","formula":"For each interval (a,b), first find z₁ = (a − μ)/σ and z₂ = (b − μ)/σ.\nUse areas measured from 0 and symmetry to calculate P(z₁ ≤ Z ≤ z₂).\nExpected frequency = 100 × P(z₁ ≤ Z ≤ z₂)."}],"table":{"headers":["Class or value","Frequency"],"rows":[["125",1],["135",1],["145",14],["155",22],["165",25],["175",19],["185",13],["195",3],["205",2]]},"workingTable":{"headers":["Class or value","Observed","Lower z","Upper z","Class probability","Expected N × P"],"rows":[["Below 120","","−∞","-2.9816514","0.0014334914","0.14334914"],["125",1,"-2.9816514","-2.3263434","0.0085666284","0.85666284"],["135",1,"-2.3263434","-1.6710354","0.037357224","3.7357224"],["145",14,"-1.6710354","-1.0157274","0.10752227","10.752227"],["155",22,"-1.0157274","-0.3604194","0.20438715","20.438715"],["165",25,"-0.3604194","0.2948886","0.25669375","25.669375"],["175",19,"0.2948886","0.95019659","0.21303331","21.303331"],["185",13,"0.95019659","1.6055046","0.11681478","11.681478"],["195",3,"1.6055046","2.2608126","0.04230597","4.230597"],["205",2,"2.2608126","2.9161206","0.010113365","1.0113365"],["Above 210","","2.9161206","∞","0.0017720675","0.17720675"]]},"shareImage":"share/q479.jpg","shareImageSize":[760,332]},{"id":480,"question":"A random variable having the normal distribution\nwith𝜇 = 18.2,𝜎 = 1.25, find the probabilities that\nit will take on a value (i) less than 16.5, (ii)\nBetween 16.5 and 18.8.","page":40,"marks":3,"answer":"Below 16.5: 0.086914962 · Between 16.5 and 18.8: 0.59747134","steps":[{"title":"Given and standardization","formula":"μ = 18.2, σ = 1.25.\nZ = (X − μ)/σ = (X − 18.2)/1.25."},{"title":"Below 16.5","formula":"When X = 16.5, z = (16.5 − 18.2)/1.25 ≈ -1.36.\nP(Z ≤ -1.36) = 0.5 − P(0 ≤ Z ≤ 1.36)  (by symmetry about 0)\nNormal table (z to 2 decimal places): P(0 ≤ Z ≤ 1.36) ≈ 0.4131.\nUsing the table: 0.5 − 0.4131 = 0.0869.\n∴ P(Z ≤ -1.36) ≈ 0.086914962 (using unrounded values)."},{"title":"Between 16.5 and 18.8","formula":"When X = 16.5, z = (16.5 − 18.2)/1.25 ≈ -1.36.\nWhen X = 18.8, z = (18.8 − 18.2)/1.25 ≈ 0.48.\nP(-1.36 ≤ Z ≤ 0.48) = P(0 ≤ Z ≤ 1.36) + P(0 ≤ Z ≤ 0.48)  (by symmetry about 0)\nNormal table (z to 2 decimal places): P(0 ≤ Z ≤ 1.36) ≈ 0.4131, P(0 ≤ Z ≤ 0.48) ≈ 0.1844.\nUsing the table: 0.4131 + 0.1844 = 0.5975.\n∴ P(-1.36 ≤ Z ≤ 0.48) ≈ 0.59747134 (using unrounded values)."}],"shareImage":"share/q480.jpg","shareImageSize":[760,266]},{"id":481,"question":"Distribution of height of 1000 soldiers is normally\ndistributed with mean 165 cms and standard\ndeviation 15 cms. How many soldiers are of height\n(i) less than 138 cms (ii) more than 198 cms (iii)\nbetween 138 and 198 cms.","page":40,"marks":3,"answer":"Below 138 cm: about 36 out of 1000 · Above 198 cm: about 14 out of 1000 · 138 to 198 cm: about 950 out of 1000","steps":[{"title":"Given and standardization","formula":"μ = 165, σ = 15.\nZ = (X − μ)/σ = (X − 165)/15."},{"title":"Below 138 cm","formula":"When X = 138, z = (138 − 165)/15 ≈ -1.8.\nP(Z ≤ -1.8) = 0.5 − P(0 ≤ Z ≤ 1.8)  (by symmetry about 0)\nNormal table (z to 2 decimal places): P(0 ≤ Z ≤ 1.8) ≈ 0.4641.\nUsing the table: 0.5 − 0.4641 = 0.0359.\n∴ P(Z ≤ -1.8) ≈ 0.035930319 (using unrounded values).\nExpected number = 1000 × 0.035930319 ≈ 35.930319."},{"title":"Above 198 cm","formula":"When X = 198, z = (198 − 165)/15 ≈ 2.2.\nP(Z ≥ 2.2) = 0.5 − P(0 ≤ Z ≤ 2.2)  (by symmetry about 0)\nNormal table (z to 2 decimal places): P(0 ≤ Z ≤ 2.2) ≈ 0.4861.\nUsing the table: 0.5 − 0.4861 = 0.0139.\n∴ P(Z ≥ 2.2) ≈ 0.013903448 (using unrounded values).\nExpected number = 1000 × 0.013903448 ≈ 13.903448."},{"title":"138 to 198 cm","formula":"When X = 138, z = (138 − 165)/15 ≈ -1.8.\nWhen X = 198, z = (198 − 165)/15 ≈ 2.2.\nP(-1.8 ≤ Z ≤ 2.2) = P(0 ≤ Z ≤ 1.8) + P(0 ≤ Z ≤ 2.2)  (by symmetry about 0)\nNormal table (z to 2 decimal places): P(0 ≤ Z ≤ 1.8) ≈ 0.4641, P(0 ≤ Z ≤ 2.2) ≈ 0.4861.\nUsing the table: 0.4641 + 0.4861 = 0.9502.\n∴ P(-1.8 ≤ Z ≤ 2.2) ≈ 0.95016623 (using unrounded values).\nExpected number = 1000 × 0.95016623 ≈ 950.16623."}],"shareImage":"share/q481.jpg","shareImageSize":[760,300]},{"id":482,"question":"In a normal distribution, 31% item are under 45 and\n8% are over 64. Find the mean and SD. Find also,\nthe percentage of items lying between 30 and 75.","page":40,"marks":5,"answer":"Mean ≈ 49.956099. SD ≈ 9.9951502. Between 30 and 75: 97.095239%.","steps":[{"title":"Standardize X = 45","formula":"P(Z ≤ z) = 0.31.\nP(0 ≤ Z ≤ |z|) = |0.31 − 0.5| = 0.19.\nUse the negative z-score: z ≈ -0.49585035.\n∴ 45 − μ ≈ (-0.49585035)σ   (1)"},{"title":"Standardize X = 64","formula":"P(Z ≤ z) = 0.92.\nP(0 ≤ Z ≤ |z|) = |0.92 − 0.5| = 0.42.\nUse the positive z-score: z ≈ 1.4050716.\n∴ 64 − μ ≈ (1.4050716)σ   (2)"},{"title":"Subtract equation (1) from equation (2)","formula":"19 ≈ [(1.4050716) − (-0.49585035)]σ.\n∴ σ ≈ 9.9951502.\nSubstitute in (1): μ = 45 − (-0.49585035)(9.9951502) ≈ 49.956099."},{"title":"Between 30 and 75","formula":"When X = 30, z = (30 − 49.956099)/9.9951502 ≈ -1.9965782.\nWhen X = 75, z = (75 − 49.956099)/9.9951502 ≈ 2.5056053.\nP(-1.9965782 ≤ Z ≤ 2.5056053) = P(0 ≤ Z ≤ 1.9965782) + P(0 ≤ Z ≤ 2.5056053)  (by symmetry about 0)\nNormal table (z to 2 decimal places): P(0 ≤ Z ≤ 2) ≈ 0.4772, P(0 ≤ Z ≤ 2.51) ≈ 0.4940.\nUsing the table: 0.4772 + 0.4940 = 0.9712.\n∴ P(-1.9965782 ≤ Z ≤ 2.5056053) ≈ 0.97095239 (using unrounded values)."}],"shareImage":"share/q482.jpg","shareImageSize":[760,233]},{"id":483,"question":"Of a large group of men, 5% are under 60 inches in\nheight and 40% are between 60 and 65 inches.\nAssuming a normal distribution, find the mean and\nstandard deviation of distribution.","page":40,"marks":4,"answer":"Mean ≈ 65.413579. SD ≈ 3.2912226.","steps":[{"title":"Standardize X = 60","formula":"P(Z ≤ z) = 0.05.\nP(0 ≤ Z ≤ |z|) = |0.05 − 0.5| = 0.45.\nUse the negative z-score: z ≈ -1.6448536.\n∴ 60 − μ ≈ (-1.6448536)σ   (1)"},{"title":"Standardize X = 65","formula":"P(Z ≤ z) = 0.45.\nP(0 ≤ Z ≤ |z|) = |0.45 − 0.5| = 0.05.\nUse the negative z-score: z ≈ -0.12566135.\n∴ 65 − μ ≈ (-0.12566135)σ   (2)"},{"title":"Subtract equation (1) from equation (2)","formula":"5 ≈ [(-0.12566135) − (-1.6448536)]σ.\n∴ σ ≈ 3.2912226.\nSubstitute in (1): μ = 60 − (-1.6448536)(3.2912226) ≈ 65.413579."}],"shareImage":"share/q483.jpg","shareImageSize":[760,266]},{"id":484,"question":"In a large group of 400 females, 28% have a weight\nless than 55 kg, and 67% have a weight between 55\nand 62 kg. Assuming a normal distribution, find the\nmean and standard deviation of the distribution.\nAlso, determine how many females have a weight\ngreater than 65 kg.","page":40,"marks":4,"answer":"Mean ≈ 56.83144. SD ≈ 3.1422612. Above 65 kg: about 2.","steps":[{"title":"Standardize X = 55","formula":"P(Z ≤ z) = 0.28.\nP(0 ≤ Z ≤ |z|) = |0.28 − 0.5| = 0.22.\nUse the negative z-score: z ≈ -0.58284151.\n∴ 55 − μ ≈ (-0.58284151)σ   (1)"},{"title":"Standardize X = 62","formula":"P(Z ≤ z) = 0.95.\nP(0 ≤ Z ≤ |z|) = |0.95 − 0.5| = 0.45.\nUse the positive z-score: z ≈ 1.6448536.\n∴ 62 − μ ≈ (1.6448536)σ   (2)"},{"title":"Subtract equation (1) from equation (2)","formula":"7 ≈ [(1.6448536) − (-0.58284151)]σ.\n∴ σ ≈ 3.1422612.\nSubstitute in (1): μ = 55 − (-0.58284151)(3.1422612) ≈ 56.83144."},{"title":"Above 65 kg","formula":"When X = 65, z = (65 − 56.83144)/3.1422612 ≈ 2.5995801.\nP(Z ≥ 2.5995801) = 0.5 − P(0 ≤ Z ≤ 2.5995801)  (by symmetry about 0)\nNormal table (z to 2 decimal places): P(0 ≤ Z ≤ 2.6) ≈ 0.4953.\nUsing the table: 0.5 − 0.4953 = 0.0047.\n∴ P(Z ≥ 2.5995801) ≈ 0.0046668944 (using unrounded values).\nExpected number = 400 × 0.0046668944 ≈ 1.8667578."}],"shareImage":"share/q484.jpg","shareImageSize":[760,329]},{"id":485,"question":"Of a large group of men, 15% are under 45 inches\nin height and 70% are between 45 and 65 inches.\nAssuming a normal distribution, find the mean and\nstandard deviation of distribution.","page":40,"marks":4,"answer":"Mean ≈ 55. SD ≈ 9.6484734.","steps":[{"title":"Standardize X = 45","formula":"P(Z ≤ z) = 0.15.\nP(0 ≤ Z ≤ |z|) = |0.15 − 0.5| = 0.35.\nUse the negative z-score: z ≈ -1.0364334.\n∴ 45 − μ ≈ (-1.0364334)σ   (1)"},{"title":"Standardize X = 65","formula":"P(Z ≤ z) = 0.85.\nP(0 ≤ Z ≤ |z|) = |0.85 − 0.5| = 0.35.\nUse the positive z-score: z ≈ 1.0364334.\n∴ 65 − μ ≈ (1.0364334)σ   (2)"},{"title":"Subtract equation (1) from equation (2)","formula":"20 ≈ [(1.0364334) − (-1.0364334)]σ.\n∴ σ ≈ 9.6484734.\nSubstitute in (1): μ = 45 − (-1.0364334)(9.6484734) ≈ 55."}],"shareImage":"share/q485.jpg","shareImageSize":[760,265]},{"id":486,"question":"The marks of 1000 students of a university are\nfound to be normally distributed with a mean of 70\nand a standard of deviation 5. Estimate the number\nof students whose marks will be (i) between 60 and\n75, (ii) more than 75, and (iii) less than 68.","page":40,"marks":4,"answer":"Between 60 and 75: about 819 out of 1000 · Above 75: about 159 out of 1000 · Below 68: about 345 out of 1000","steps":[{"title":"Given and standardization","formula":"μ = 70, σ = 5.\nZ = (X − μ)/σ = (X − 70)/5."},{"title":"Between 60 and 75","formula":"When X = 60, z = (60 − 70)/5 ≈ -2.\nWhen X = 75, z = (75 − 70)/5 ≈ 1.\nP(-2 ≤ Z ≤ 1) = P(0 ≤ Z ≤ 2) + P(0 ≤ Z ≤ 1)  (by symmetry about 0)\nNormal table (z to 2 decimal places): P(0 ≤ Z ≤ 2) ≈ 0.4772, P(0 ≤ Z ≤ 1) ≈ 0.3413.\nUsing the table: 0.4772 + 0.3413 = 0.8185.\n∴ P(-2 ≤ Z ≤ 1) ≈ 0.81859461 (using unrounded values).\nExpected number = 1000 × 0.81859461 ≈ 818.59461."},{"title":"Above 75","formula":"When X = 75, z = (75 − 70)/5 ≈ 1.\nP(Z ≥ 1) = 0.5 − P(0 ≤ Z ≤ 1)  (by symmetry about 0)\nNormal table (z to 2 decimal places): P(0 ≤ Z ≤ 1) ≈ 0.3413.\nUsing the table: 0.5 − 0.3413 = 0.1587.\n∴ P(Z ≥ 1) ≈ 0.15865525 (using unrounded values).\nExpected number = 1000 × 0.15865525 ≈ 158.65525."},{"title":"Below 68","formula":"When X = 68, z = (68 − 70)/5 ≈ -0.4.\nP(Z ≤ -0.4) = 0.5 − P(0 ≤ Z ≤ 0.4)  (by symmetry about 0)\nNormal table (z to 2 decimal places): P(0 ≤ Z ≤ 0.4) ≈ 0.1554.\nUsing the table: 0.5 − 0.1554 = 0.3446.\n∴ P(Z ≤ -0.4) ≈ 0.34457826 (using unrounded values).\nExpected number = 1000 × 0.34457826 ≈ 344.57826."}],"shareImage":"share/q486.jpg","shareImageSize":[760,297]},{"id":487,"question":"The lifetime of a certain batteries has a mean life of\n400 hours and the standard deviation as 45 hours.\nAssuming the distribution of lifetime to be normal,\nfind (i) the percentage of batteries with a lifetime of\nat least 470 hours, (ii) the proportion of batteries\nwith a lifetime between 385 and 415 hours, and (iii)\nthe minimum life of the best 5% of batteries.","page":40,"marks":4,"answer":"(i) 5.9906907%. (ii) 0.26111732. (iii) 474.01841 hours.","steps":[{"title":"At least 470 hours","formula":"1 − Φ((470−400)/45) ≈ 0.059906907."},{"title":"Between 385 and 415 hours","formula":"Φ(15/45) − Φ(−15/45) ≈ 0.26111732."},{"title":"Find the top 5% threshold","formula":"Use the 95th percentile: 400 + 45Φ⁻¹(0.95) ≈ 474.01841."}],"shareImage":"share/q487.jpg","shareImageSize":[760,360]},{"id":488,"question":"The marks obtained by students in an examination\nfollow a normal distribution. If 30% of the students\ngot marks below 35 and 10% got marks above 60,\nfind the mean and percentage of students who got\nmarks between 40 and 50.","page":40,"marks":5,"answer":"Mean ≈ 42.259336. SD ≈ 13.843114. Between 40 and 50: 27.680089%.","steps":[{"title":"Standardize X = 35","formula":"P(Z ≤ z) = 0.3.\nP(0 ≤ Z ≤ |z|) = |0.3 − 0.5| = 0.2.\nUse the negative z-score: z ≈ -0.52440051.\n∴ 35 − μ ≈ (-0.52440051)σ   (1)"},{"title":"Standardize X = 60","formula":"P(Z ≤ z) = 0.9.\nP(0 ≤ Z ≤ |z|) = |0.9 − 0.5| = 0.4.\nUse the positive z-score: z ≈ 1.2815516.\n∴ 60 − μ ≈ (1.2815516)σ   (2)"},{"title":"Subtract equation (1) from equation (2)","formula":"25 ≈ [(1.2815516) − (-0.52440051)]σ.\n∴ σ ≈ 13.843114.\nSubstitute in (1): μ = 35 − (-0.52440051)(13.843114) ≈ 42.259336."},{"title":"Between 40 and 50","formula":"When X = 40, z = (40 − 42.259336)/13.843114 ≈ -0.1632101.\nWhen X = 50, z = (50 − 42.259336)/13.843114 ≈ 0.55917073.\nP(-0.1632101 ≤ Z ≤ 0.55917073) = P(0 ≤ Z ≤ 0.1632101) + P(0 ≤ Z ≤ 0.55917073)  (by symmetry about 0)\nNormal table (z to 2 decimal places): P(0 ≤ Z ≤ 0.16) ≈ 0.0636, P(0 ≤ Z ≤ 0.56) ≈ 0.2123.\nUsing the table: 0.0636 + 0.2123 = 0.2759.\n∴ P(-0.1632101 ≤ Z ≤ 0.55917073) ≈ 0.27680089 (using unrounded values)."}],"shareImage":"share/q488.jpg","shareImageSize":[760,316]},{"id":489,"question":"Find the mean and standard deviation in which 7%\nof items are under 35 and 89% are under 63.","page":41,"marks":4,"answer":"Mean ≈ 50.291365. SD ≈ 10.36147.","steps":[{"title":"Standardize X = 35","formula":"P(Z ≤ z) = 0.07.\nP(0 ≤ Z ≤ |z|) = |0.07 − 0.5| = 0.43.\nUse the negative z-score: z ≈ -1.475791.\n∴ 35 − μ ≈ (-1.475791)σ   (1)"},{"title":"Standardize X = 63","formula":"P(Z ≤ z) = 0.89.\nP(0 ≤ Z ≤ |z|) = |0.89 − 0.5| = 0.39.\nUse the positive z-score: z ≈ 1.2265281.\n∴ 63 − μ ≈ (1.2265281)σ   (2)"},{"title":"Subtract equation (1) from equation (2)","formula":"28 ≈ [(1.2265281) − (-1.475791)]σ.\n∴ σ ≈ 10.36147.\nSubstitute in (1): μ = 35 − (-1.475791)(10.36147) ≈ 50.291365."}],"shareImage":"share/q489.jpg","shareImageSize":[760,201]},{"id":490,"question":"If X is a normal variate with a mean of 120 and a\nstandard deviation of 10, fine c such that\n(1) 𝑃( 𝑋 > 𝑐 ) = 0.02 and (2) 𝑃( 𝑋 < 𝑐 ) = 0.05","page":41,"marks":4,"answer":"(i) Upper 2% cutoff: 140.53749 · (ii) Lower 5% cutoff: 103.55146","steps":[{"title":"Given and standardization","formula":"μ = 120, σ = 10.\nZ = (X − μ)/σ."},{"title":"(i) Upper 2% cutoff","formula":"P(Z ≤ z) = 0.98.\nP(0 ≤ Z ≤ |z|) = |0.98 − 0.5| = 0.48.\nUse the positive z-score: z ≈ 2.0537489.\n∴ x = μ + σz = 120 + 10(2.0537489) ≈ 140.53749."},{"title":"(ii) Lower 5% cutoff","formula":"P(Z ≤ z) = 0.05.\nP(0 ≤ Z ≤ |z|) = |0.05 − 0.5| = 0.45.\nUse the negative z-score: z ≈ -1.6448536.\n∴ x = μ + σz = 120 + 10(-1.6448536) ≈ 103.55146."}],"shareImage":"share/q490.jpg","shareImageSize":[760,234]},{"id":491,"question":"If X is a normal variate with a mean of 25 and SD\nof 5, Find the value of 𝑋 = 𝑥 such that\n1\n𝑃(𝑋 ≤ 𝑥 ) = 0.01\n1","page":41,"marks":4,"answer":"Lower 1% cutoff: 13.368261","steps":[{"title":"Given and standardization","formula":"μ = 25, σ = 5.\nZ = (X − μ)/σ."},{"title":"Lower 1% cutoff","formula":"P(Z ≤ z) = 0.01.\nP(0 ≤ Z ≤ |z|) = |0.01 − 0.5| = 0.49.\nUse the negative z-score: z ≈ -2.3263479.\n∴ x = μ + σz = 25 + 5(-2.3263479) ≈ 13.368261."}],"shareImage":"share/q491.jpg","shareImageSize":[760,235]},{"id":492,"question":"If 𝑋 is normal variate with a mean of 30 and an SD\nof 6, find the value of 𝑋 = 𝑥 such that\n1\n𝑃(𝑋 ≤ 𝑥 ) = 0.05.\n1","page":41,"marks":4,"answer":"Lower 5% cutoff: 20.130878","steps":[{"title":"Given and standardization","formula":"μ = 30, σ = 6.\nZ = (X − μ)/σ."},{"title":"Lower 5% cutoff","formula":"P(Z ≤ z) = 0.05.\nP(0 ≤ Z ≤ |z|) = |0.05 − 0.5| = 0.45.\nUse the negative z-score: z ≈ -1.6448536.\n∴ x = μ + σz = 30 + 6(-1.6448536) ≈ 20.130878."}],"shareImage":"share/q492.jpg","shareImageSize":[760,235]},{"id":493,"question":"Fit a normal distribution to the data below.","page":41,"marks":4,"answer":"Expected frequencies in the printed classes: 2.9030687, 30.86142, 148.00016, 322.14046, 319.36791, 144.20567, 29.5503, 2.731259.","steps":[{"title":"Given and distribution parameters","formula":"Use class midpoints m. Compute μ = Σfm/N and σ = √[Σf(m−μ)²/N].\nN = 1000, μ ≈ 79.945, σ ≈ 5.4449036."},{"title":"Find the class boundaries","formula":"Boundaries: 60, 65, 70, 75, 80, 85, 90, 95, 100. Use the midpoint between adjacent values or between the ends of adjacent classes."},{"title":"Calculate the expected frequencies","formula":"For each interval (a,b), first find z₁ = (a − μ)/σ and z₂ = (b − μ)/σ.\nUse areas measured from 0 and symmetry to calculate P(z₁ ≤ Z ≤ z₂).\nExpected frequency = 1000 × P(z₁ ≤ Z ≤ z₂)."}],"table":{"headers":["Class or value","Frequency"],"rows":[["60–65",3],["65–70",21],["70–75",150],["75–80",335],["80–85",326],["85–90",135],["90–95",26],["95–100",4]]},"workingTable":{"headers":["Class or value","Observed","Lower z","Upper z","Class probability","Expected N × P"],"rows":[["Below 60","","−∞","-3.6630584","0.00012461083","0.12461083"],["60–65",3,"-3.6630584","-2.7447685","0.0029030687","2.9030687"],["65–70",21,"-2.7447685","-1.8264786","0.03086142","30.86142"],["70–75",150,"-1.8264786","-0.90818872","0.14800016","148.00016"],["75–80",335,"-0.90818872","0.010101189","0.32214046","322.14046"],["80–85",326,"0.010101189","0.9283911","0.31936791","319.36791"],["85–90",135,"0.9283911","1.846681","0.14420567","144.20567"],["90–95",26,"1.846681","2.7649709","0.0295503","29.5503"],["95–100",4,"2.7649709","3.6832608","0.002731259","2.731259"],["Above 100","","3.6832608","∞","0.00011513467","0.11513467"]]},"shareImage":"share/q493.jpg","shareImageSize":[760,423]},{"id":494,"question":"In an examination, it is laid down that a student\npasses if he secures 40% or more. He is placed in\nthe first, second and third division according to\nwhether he secures 60% or more marks, between\n50% and 60% marks and between 40% and 50%\nmarks respectively. He gets a distinction in case he\nsecures 75% or more. It is noticed from the result\nthat 10% of the students failed in the examination,\nwhereas 5% of them obtained distinction. Calculate\nthe percentage of students placed in the second\ndivision. (Assume Normal Distribution of marks.)","page":41,"marks":4,"answer":"Mean ≈ 55.327442. SD ≈ 11.960066. Second division: 32.398067%.","steps":[{"title":"Standardize X = 40","formula":"P(Z ≤ z) = 0.1.\nP(0 ≤ Z ≤ |z|) = |0.1 − 0.5| = 0.4.\nUse the negative z-score: z ≈ -1.2815516.\n∴ 40 − μ ≈ (-1.2815516)σ   (1)"},{"title":"Standardize X = 75","formula":"P(Z ≤ z) = 0.95.\nP(0 ≤ Z ≤ |z|) = |0.95 − 0.5| = 0.45.\nUse the positive z-score: z ≈ 1.6448536.\n∴ 75 − μ ≈ (1.6448536)σ   (2)"},{"title":"Subtract equation (1) from equation (2)","formula":"35 ≈ [(1.6448536) − (-1.2815516)]σ.\n∴ σ ≈ 11.960066.\nSubstitute in (1): μ = 40 − (-1.2815516)(11.960066) ≈ 55.327442."},{"title":"Second division","formula":"When X = 50, z = (50 − 55.327442)/11.960066 ≈ -0.4454358.\nWhen X = 60, z = (60 − 55.327442)/11.960066 ≈ 0.39067997.\nP(-0.4454358 ≤ Z ≤ 0.39067997) = P(0 ≤ Z ≤ 0.4454358) + P(0 ≤ Z ≤ 0.39067997)  (by symmetry about 0)\nNormal table (z to 2 decimal places): P(0 ≤ Z ≤ 0.45) ≈ 0.1736, P(0 ≤ Z ≤ 0.39) ≈ 0.1517.\nUsing the table: 0.1736 + 0.1517 = 0.3253.\n∴ P(-0.4454358 ≤ Z ≤ 0.39067997) ≈ 0.32398067 (using unrounded values)."}],"shareImage":"share/q494.jpg","shareImageSize":[760,488]},{"id":495,"question":"Let X have density f(x) = ce^(−2x) for x > 0. Find (i) P(X > 2) and (ii) P(X < 1/c).","page":41,"marks":3,"answer":"(i) P(X > 2): 0.018315639 · (ii) P(X < 1/c): 0.63212056","steps":[{"title":"Given and preliminary calculation","formula":"A density has total area 1.\n∫ ce^(−2x) dx  [from 0 to ∞] = [−(c/2)e^(−2x)]  [from 0 to ∞] = c/2.\nTherefore c/2 = 1, giving c = 2 and 1/c = 1/2."},{"title":"Given and probability density","formula":"λ = 2.\nf(x) = λe^(−λx) = 2e^(−2x), x > 0."},{"title":"(i) P(X > 2)","formula":"Integrate f(x) from 2 to ∞.\n∫ (2)e^(−2x) dx  [from 2 to ∞]\n= [−e^(−2x)]  [from 2 to ∞]\n= e^(−4) ≈ 0.018315639."},{"title":"(ii) P(X < 1/c)","formula":"Integrate f(x) from 0 to 0.5.\n∫ (2)e^(−2x) dx  [from 0 to 0.5]\n= [−e^(−2x)]  [from 0 to 0.5]\n= 1 − e^(−1) ≈ 0.63212056."}],"shareImage":"share/q495.jpg","shareImageSize":[760,249]},{"id":496,"question":"The mileage which car owners get with a certain\nkind of radial tire is a random variable having an\nexponential distribution with mean 4000 km. Find\nthe probabilities that one of these tires will last (i)\nat least 2000 km (ii) at most 3000 km.","page":41,"marks":3,"answer":"At least 2000 km: 0.60653066 · At most 3000 km: 0.52763345","steps":[{"title":"Given and probability density","formula":"λ = 0.00025.\nf(x) = λe^(−λx) = 0.00025e^(−0.00025x), x > 0."},{"title":"At least 2000 km","formula":"Integrate f(x) from 2000 to ∞.\n∫ (0.00025)e^(−0.00025x) dx  [from 2000 to ∞]\n= [−e^(−0.00025x)]  [from 2000 to ∞]\n= e^(−0.5) ≈ 0.60653066."},{"title":"At most 3000 km","formula":"Integrate f(x) from 0 to 3000.\n∫ (0.00025)e^(−0.00025x) dx  [from 0 to 3000]\n= [−e^(−0.00025x)]  [from 0 to 3000]\n= 1 − e^(−0.75) ≈ 0.52763345."}],"shareImage":"share/q496.jpg","shareImageSize":[760,297]},{"id":497,"question":"The average time it takes to serve a customer at a\npetrol pump is 6 minutes. The service time follows\nexponential distribution. Calculate the probability\nthat (i) A customer will take less than 2 minutes to\ncomplete the service. (ii) A customer will take\nbetween 4 and 5 minutes to get the service. (iii) A\ncustomer will take more than 10 minutes for his\nservice.","page":41,"marks":4,"answer":"Under two minutes: 0.28346869 · Four to five minutes: 0.078818911 · More than ten minutes: 0.1888756","steps":[{"title":"Given and probability density","formula":"λ = 0.16666667.\nf(x) = λe^(−λx) = 0.16666667e^(−0.16666667x), x > 0."},{"title":"Under two minutes","formula":"Integrate f(x) from 0 to 2.\n∫ (0.16666667)e^(−0.16666667x) dx  [from 0 to 2]\n= [−e^(−0.16666667x)]  [from 0 to 2]\n= 1 − e^(−0.33333333) ≈ 0.28346869."},{"title":"Four to five minutes","formula":"Integrate f(x) from 4 to 5.\n∫ (0.16666667)e^(−0.16666667x) dx  [from 4 to 5]\n= [−e^(−0.16666667x)]  [from 4 to 5]\n= e^(−0.66666667) − e^(−0.83333333) ≈ 0.078818911."},{"title":"More than ten minutes","formula":"Integrate f(x) from 10 to ∞.\n∫ (0.16666667)e^(−0.16666667x) dx  [from 10 to ∞]\n= [−e^(−0.16666667x)]  [from 10 to ∞]\n= e^(−1.6666667) ≈ 0.1888756."}],"shareImage":"share/q497.jpg","shareImageSize":[760,392]},{"id":498,"question":"Daily milk consumption above 20,000 gallons is exponential with rate 1/3000. The daily stock is 35,000 gallons. Find the probability that the stock is insufficient on both of two randomly selected days.","page":41,"marks":4,"answer":"4.539993e-05","steps":[{"title":"Given and formula","formula":"Stock is insufficient when the excess over 20,000 gallons exceeds 15,000 gallons."},{"title":"Substitution and result","formula":"One day: e^(−15000/3000) = e⁻⁵. For two independent days, square it: e⁻¹⁰."}],"shareImage":"share/q498.jpg","shareImageSize":[760,341]},{"id":499,"question":"The lifetime 𝑇 of an alkline battery is exponentially\ndistributed with 𝜆 = 0.05 per hour.\n(a) What are the mean are standard deviation of the\nbattery’s lifetime?\n(b) What are the probabilities for the battery to last\nbetween 10 and 15 hours and to last more than 20\nhours?","page":41,"marks":4,"answer":"Between 10 and 15 hours: 0.13416411 · Over 20 hours: 0.36787944 · Mean = SD = 20 hours","steps":[{"title":"Given and probability density","formula":"λ = 0.05.\nf(x) = λe^(−λx) = 0.05e^(−0.05x), x > 0."},{"title":"Between 10 and 15 hours","formula":"Integrate f(x) from 10 to 15.\n∫ (0.05)e^(−0.05x) dx  [from 10 to 15]\n= [−e^(−0.05x)]  [from 10 to 15]\n= e^(−0.5) − e^(−0.75) ≈ 0.13416411."},{"title":"Over 20 hours","formula":"Integrate f(x) from 20 to ∞.\n∫ (0.05)e^(−0.05x) dx  [from 20 to ∞]\n= [−e^(−0.05x)]  [from 20 to ∞]\n= e^(−1) ≈ 0.36787944."},{"title":"Find mean and SD","formula":"For an exponential lifetime, both are 1/λ = 1/0.05 = 20 hours."}],"shareImage":"share/q499.jpg","shareImageSize":[760,392]},{"id":500,"question":"The time between breakdown of a particular\nmachine follows an exponential distribution with a\nmean of 17 days. Calculate the probability that a\nmachine breaks down in a 15 day period.","page":42,"marks":3,"answer":"Breakdown within 15 days: 0.5861919","steps":[{"title":"Given and probability density","formula":"λ = 0.058823529.\nf(x) = λe^(−λx) = 0.058823529e^(−0.058823529x), x > 0."},{"title":"Breakdown within 15 days","formula":"Integrate f(x) from 0 to 15.\n∫ (0.058823529)e^(−0.058823529x) dx  [from 0 to 15]\n= [−e^(−0.058823529x)]  [from 0 to 15]\n= 1 − e^(−0.88235294) ≈ 0.5861919."}],"shareImage":"share/q500.jpg","shareImageSize":[760,266]},{"id":501,"question":"Machine repair time X is exponential with rate 1/2 per hour. Find (i) P(X > 2) and (ii) P(X ≥ 11 | X > 8).","page":42,"marks":3,"answer":"Repair time exceeds two hours: 0.36787944 · At least 11 hours given over eight hours: 0.22313016","steps":[{"title":"Given and preliminary calculation","formula":"By the memoryless property, P(X ≥ 11 | X > 8) = P(X ≥ 11 − 8) = P(X ≥ 3)."},{"title":"Given and probability density","formula":"λ = 0.5.\nf(x) = λe^(−λx) = 0.5e^(−0.5x), x > 0."},{"title":"Repair time exceeds two hours","formula":"Integrate f(x) from 2 to ∞.\n∫ (0.5)e^(−0.5x) dx  [from 2 to ∞]\n= [−e^(−0.5x)]  [from 2 to ∞]\n= e^(−1) ≈ 0.36787944."},{"title":"At least 11 hours given over eight hours","formula":"Integrate f(x) from 3 to ∞.\n∫ (0.5)e^(−0.5x) dx  [from 3 to ∞]\n= [−e^(−0.5x)]  [from 3 to ∞]\n= e^(−1.5) ≈ 0.22313016."}],"shareImage":"share/q501.jpg","shareImageSize":[760,343]},{"id":502,"question":"The Life length X of an electronic component\nfollows an exponential distribution. These are 2\nProcesses by which the component may be\nmanufactured. The Expected life length of\ncomponent is 100 hrs if process I is used to\nmanufacture while it is 150 hrs if process II is used.\nThe cost of manufacturing a single component by\nprocess I is Rs. 10, while is Rs.20 for Process II.\nMoreover, if the component lasts less than the\nguaranteed life of 200 hrs, a loss of Rs. 50 is to be\nborne by the manufacturer. Which process is\nAdvantageous to the manufacturer?","page":42,"marks":5,"answer":"Process I. Expected costs: Rs. 53.23 and Rs. 56.82.","steps":[{"title":"Given and formula","formula":"For mean m, the chance of a warranty loss is P(X < 200) = 1 − e^(−200/m)."},{"title":"Substitution and result","formula":"Process I: 10 + 50(1 − e⁻²). Process II: 20 + 50(1 − e^(−200/150)). Choose the smaller expected cost."}],"shareImage":"share/q502.jpg","shareImageSize":[760,519]},{"id":503,"question":"The length of the shower on a tropical island during\nrainy season has an exponential distribution, with\nparameter λ = 2, time being measured in minutes.\nWhat is the probability that a shower will last more\nthan three minutes? If a shower has already lasted\nfor 2 minutes, what is the probability that it will last\nfor at least one more minute?","page":42,"marks":3,"answer":"More than three minutes: 0.0024787522 · At least one more minute given two elapsed: 0.13533528","steps":[{"title":"Given and probability density","formula":"λ = 2.\nf(x) = λe^(−λx) = 2e^(−2x), x > 0."},{"title":"More than three minutes","formula":"Integrate f(x) from 3 to ∞.\n∫ (2)e^(−2x) dx  [from 3 to ∞]\n= [−e^(−2x)]  [from 3 to ∞]\n= e^(−6) ≈ 0.0024787522."},{"title":"At least one more minute given two elapsed","formula":"Integrate f(x) from 1 to ∞.\n∫ (2)e^(−2x) dx  [from 1 to ∞]\n= [−e^(−2x)]  [from 1 to ∞]\n= e^(−2) ≈ 0.13533528."}],"note":"The exponential distribution is memoryless, so the second event uses the one-minute survival probability.","shareImage":"share/q503.jpg","shareImageSize":[760,361]},{"id":504,"question":"The life of an electronic component follows\nexponential distribution with a mean of 4 years.\nThe manufacturer of this component gives a\nreplacement warranty of 3 years.\n(a) What proportion of components will be\nreplaced in the period of warranty?\n(b) What is the probability that a randomly selected\ncomponent will have life within two standard\ndeviations of the mean life?","page":42,"marks":4,"answer":"Replaced under warranty: 0.52763345 · Within two standard deviations of the mean: 0.95021293","steps":[{"title":"Given and probability density","formula":"λ = 0.25.\nf(x) = λe^(−λx) = 0.25e^(−0.25x), x > 0."},{"title":"Replaced under warranty","formula":"Integrate f(x) from 0 to 3.\n∫ (0.25)e^(−0.25x) dx  [from 0 to 3]\n= [−e^(−0.25x)]  [from 0 to 3]\n= 1 − e^(−0.75) ≈ 0.52763345."},{"title":"Within two standard deviations of the mean","formula":"Integrate f(x) from 0 to 12.\n∫ (0.25)e^(−0.25x) dx  [from 0 to 12]\n= [−e^(−0.25x)]  [from 0 to 12]\n= 1 − e^(−3) ≈ 0.95021293."}],"note":"Mean and SD both equal four years. The interval [4−8, 4+8] meets the support in [0,12].","shareImage":"share/q504.jpg","shareImageSize":[760,424]},{"id":505,"question":"If 𝑋 isan exponentially distributed random variable\nwith parameter 𝜆, find the value of k such that\n𝑃(𝑋 > 𝑘) = 𝑎𝑃(𝑋 ≤ 𝑘)","page":42,"marks":3,"answer":"k = ln((1+a)/a)/λ for a > 0","steps":[{"title":"Given and formula","formula":"P(X > k) = aP(X ≤ k) = a[1 − P(X > k)].\n∴ (1 + a)P(X > k) = a."},{"title":"Substitution and result","formula":"P(X > k) = ∫ λe^(−λx) dx  [from k to ∞] = e^(−λk).\n∴ e^(−λk) = a/(1+a).\nTaking logs gives k = ln((1+a)/a)/λ for a > 0. For a = 0 there is no finite solution."}],"shareImage":"share/q505.jpg","shareImageSize":[760,235]},{"id":506,"question":"The length of time X to complete a job is\nexponentially distributed with 𝐸(𝑋) = µ = 10\nhours. (i) Compute the probability of job\ncompletion between two consecutive jobs\nexceeding 20 hours. (ii) The cost of job completion\nis given by 𝐶 = 4 + 2𝑋 + 4𝑋2. Find the expected\nvalue of C.","page":42,"marks":3,"answer":"Time exceeds 20 hours: 0.13533528 · E[C] = 824","steps":[{"title":"Given and probability density","formula":"λ = 0.1.\nf(x) = λe^(−λx) = 0.1e^(−0.1x), x > 0."},{"title":"Time exceeds 20 hours","formula":"Integrate f(x) from 20 to ∞.\n∫ (0.1)e^(−0.1x) dx  [from 20 to ∞]\n= [−e^(−0.1x)]  [from 20 to ∞]\n= e^(−2) ≈ 0.13533528."},{"title":"Find the expected cost","formula":"E[X] = 10 and E[X²] = Var(X) + E[X]² = 100 + 100 = 200. Therefore E[C] = 4 + 2(10) + 4(200) = 824."}],"shareImage":"share/q506.jpg","shareImageSize":[760,362]},{"id":507,"question":"In a newly constructed township, 2000 electric\nlamps are installed with an average life of 1000\nburning hours and standard deviation of 200 hours.\nAssuming the life of the lamps follows normal\ndistribution, find (𝑖) The number of lamps expected\nto fail during the first 700 hours.(𝑖𝑖) In which\nperiod of burning hours 10% of the lamps fail.","page":42,"marks":3,"answer":"(i) About 134 lamps. (ii) About 743.69 hours.","steps":[{"title":"Count failures before 700 hours","formula":"z = (700−1000)/200 = −1.5. Expected failures = 2000Φ(−1.5) ≈ 133.6144."},{"title":"Find when 10% have failed","formula":"The tenth percentile is 1000 + 200Φ⁻¹(0.10) ≈ 743.68969 hours."}],"shareImage":"share/q507.jpg","shareImageSize":[760,364]}]};
